def _parse():
    data={}
    for raw in RAW.splitlines():
        parts=raw.split("|")
        if len(parts)!=len(KEYS)+1:
            raise ValueError("Bid campaign has an incomplete translation: "+raw[:32])
        code=parts[0]
        if code in data or not all(part.strip() for part in parts[1:]):
            raise ValueError("Duplicate or empty translation: "+code)
        data[code]=dict(zip(KEYS,parts[1:]))
    if set(data)!=set(LOCALES):
        raise ValueError("Bid launch languages differ from app languages: "+
                         str(sorted(set(LOCALES)^set(data))))
    return data

COPY=_parse()

def copy(code):
    return COPY.get(code,COPY["en-US"])
